// Some portions generated by Codex
package org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades;

import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.Map;
import java.util.Set;

import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.JoinFactorCostModel;
import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cost.EvidenceProfile;
import org.junit.jupiter.api.Test;

/**
 * Review reproducers for cost-vector / estimate-vector sanity invariants (candidates 1 and 4). Every assertion states
 * the robust expectation; a failure demonstrates the finding.
 */
class CostModelInvariantReviewReproTest {

	@Test
	void saturatedUnknownSubtreeMustNotHideElevenOrdersOfMagnitude() {
		CostVector unknown = new CostVector(Double.NaN, Double.NaN, 0.0d, 0.0d, 0.0d, 4.0d, 0.5d);
		CostVector cheapRest = new CostVector(10.0d, 10.0d, 0.0d, 5.0d, 0.0d, 1.0d, 1.0d);
		CostVector hugeRest = new CostVector(1.0e12d, 1.0e12d, 0.0d, 0.0d, 0.0d, 1.0d, 1.0d);
		CostVector cheapPlan = unknown.plus(cheapRest);
		CostVector hugePlan = unknown.plus(hugeRest);
		assertTrue(cheapPlan.compareTo(hugePlan) < 0,
				"unknown+10 rows must beat unknown+1e12 rows; objective cheap=" + cheapPlan.objectiveScore()
						+ " huge=" + hugePlan.objectiveScore() + " compare=" + cheapPlan.compareTo(hugePlan));
	}

	@Test
	void filterMustNeverRaiseTheUpperRowBound() {
		EstimateVector scan = EstimateVector.heuristic(100.0d, 4.0d, "scan");
		EstimateVector filtered = scan.filter(0.5d, null, "filter");
		assertTrue(filtered.upperRows() <= scan.upperRows(),
				"a filter cannot produce more rows than its input: input upper=" + scan.upperRows()
						+ " filtered upper=" + filtered.upperRows());
	}

	@Test
	void largerReportedQErrorMustNotShrinkUncertainty() {
		JoinFactorCostModel.FactorCostEstimate defaultQError = new JoinFactorCostModel.FactorCostEstimate(1_000.0d,
				1_000.0d);
		JoinFactorCostModel.FactorCostEstimate hundredfoldQError = new JoinFactorCostModel.FactorCostEstimate(
				1_000.0d, 1_000.0d, Map.of(), Map.of("plannedCardinalityQError", 100.0d));
		EstimateVector q4 = defaultQError.getNormalizedEstimateVector();
		EstimateVector q100 = hundredfoldQError.getNormalizedEstimateVector();
		assertTrue(q100.uncertaintyRows() >= q4.uncertaintyRows(),
				"q-error 100 reports uncertainty " + q100.uncertaintyRows() + " [" + q100.lowerRows() + ","
						+ q100.upperRows() + "] while default q-error 4 reports " + q4.uncertaintyRows() + " ["
						+ q4.lowerRows() + "," + q4.upperRows() + "]");
	}

	@Test
	void lowConfidenceZeroMustNotBecomeAConfidentZeroThroughSemiJoin() {
		EvidenceProfile left = EvidenceProfile.of(1_000.0d, 1_000.0d, 0.0d, 0.9d, "left", Map.of(), Map.of(),
				Map.of(), Map.of());
		EvidenceProfile guessedEmptyRight = EvidenceProfile.of(0.0d, 0.0d, 0.0d, 0.05d, "sketch-miss", Map.of(),
				Map.of(), Map.of(), Map.of());
		EvidenceProfile exists = left.semiJoin(guessedEmptyRight, Set.of("x"));
		assertTrue(exists.rows() > 0.0d || exists.confidence() <= guessedEmptyRight.confidence(),
				"EXISTS over a 5%-confidence zero estimate yields rows=" + exists.rows() + " at confidence "
						+ exists.confidence());
	}
}
